// Private fixture on stdin. Use the built Web application and the real loopback
// user router. No responses are intercepted or generated by the browser test.
import { chromium } from '@playwright/test';
import { preview } from 'vite';
import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const root=fileURLToPath(new URL('../',import.meta.url));
const tls=resolve(root,'../../.local/tls');
let input='';
for await (const chunk of process.stdin) input+=chunk;
const f=JSON.parse(input);
const upstream=new URL(f.api);
if(upstream.protocol!=='http:'||upstream.hostname!=='127.0.0.1'||!upstream.port ||
    f.origin!=='https://127.0.0.1:43122' || typeof f.token!=='string')throw Error('Expected a private loopback user fixture');
const server=await preview({root,configFile:false,logLevel:'silent',preview:{host:'127.0.0.1',port:43122,strictPort:true,
  https:{key:readFileSync(resolve(tls,'key.pem')),cert:readFileSync(resolve(tls,'cert.pem'))},
  proxy:{'/api/v1/':{target:upstream.origin,changeOrigin:false}}}});
let browser;
try {
  browser=await chromium.launch({channel:'chrome',headless:true});
  const context=await browser.newContext({baseURL:f.origin,ignoreHTTPSErrors:true,viewport:{width:1280,height:960}});
  await context.addCookies([{name:'__Host-orange-user',value:f.token,url:f.origin,secure:true,httpOnly:true,sameSite:'Lax'}]);
  const page=await context.newPage();
  page.setDefaultTimeout(15000);
  const checked=[];
  for(const provider of ['github','gitlab']){
    await page.goto('/agent/runs/'+encodeURIComponent(f.run)+'/repositories/'+provider);
    await page.getByRole('combobox',{name:'仓库数据源'}).click();
    await page.locator('.ant-select-item-option-content').filter({hasText:provider}).click();
    await page.getByRole('checkbox',{name:'acme/notes'}).check();
    const grantReply=page.waitForResponse(r=>r.request().method()==='POST'&&new URL(r.url()).pathname.endsWith('/connectors/'+provider));
    await page.getByRole('button',{name:'授权读取所选仓库 15 分钟'}).click();
    const grant=await (await grantReply).json();
    if(!grant.grant_id)throw Error('Missing provider grant');
    const section=page.getByRole('region',{name:'仓库授权 '+grant.grant_id});
    await section.getByRole('button',{name:'列出已授权'+(provider==='github'?'仓库':'项目')}).click();
    await section.getByRole('button',{name:'acme/notes',exact:true}).click();
    await section.getByRole('button',{name:'列出问题单'}).click();
    await section.getByRole('button',{name:'#1 Restricted fixture'}).click();
    await section.locator('pre').filter({hasText:'private fixture bytes'}).waitFor();
    await section.getByRole('button',{name:provider==='github'?'列出PR':'列出MR'}).click();
    await section.getByRole('button',{name:'#2 Review fixture'}).click();
    await section.locator('pre').filter({hasText:'reviewed changes'}).waitFor();
    await section.getByLabel('仓库内文件路径').fill('docs/scope.txt');
    await section.getByRole('button',{name:'读取文件版本'}).click();
    const download=page.waitForEvent('download');
    await section.getByRole('button',{name:'下载已校验文件'}).click();
    const file=await download;
    if(file.suggestedFilename()!=='scope.txt'||!readFileSync(await file.path()).equals(Buffer.from('registered file\n')))throw Error('Unexpected pinned file bytes');
    if(f.screenshot)await page.screenshot({path:f.screenshot+'.'+provider+'.png',fullPage:true});
    await section.getByRole('button',{name:'撤销仓库授权'}).click();
    await section.getByText('已撤销',{exact:true}).waitFor();
    await page.reload();
    await section.getByText('已撤销',{exact:true}).waitFor();
    if(await section.getByRole('button',{name:'下载已校验文件'}).count())throw Error('Revoked attachment visible');
    checked.push(provider);
  }
  process.stdout.write(JSON.stringify({providers:checked,read_issue:true,read_change:true,file_verified:true,revoked_after_reload:true})+'\n');
} finally {
  if(browser)await browser.close();
  await server.close();
}
